import 'dart:convert';

import 'package:cerne/features/chat/domain/entities/chat_message.dart';
import 'package:cerne/features/chat/domain/entities/chat_session.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

/// On-device, cross-restart persistence for chat (research.md R4) —
/// Keychain-backed, same pattern `EntriesLocalCache` already establishes.
/// Four **independent** storage keys so one write never clobbers another.
class ChatLocalCache {
  ChatLocalCache({FlutterSecureStorage? storage})
    : _storage = storage ?? const FlutterSecureStorage();

  final FlutterSecureStorage _storage;

  static const _sessionsKey = 'chatSessionsLocalCache';
  static const _messagesKey = 'chatMessagesLocalCache';
  static const _lastActiveKey = 'chatLastActiveSessionId';
  static const _savedMessageEntryIdsKey = 'chatSavedMessageEntryIds';

  Future<List<ChatSession>> readSessions() async {
    final raw = await _storage.read(key: _sessionsKey);
    if (raw == null) return const [];
    try {
      final decoded = jsonDecode(raw) as List<dynamic>;
      return decoded
          .map((e) => _sessionFromJson(e as Map<String, dynamic>))
          .toList();
    } on FormatException {
      return const [];
    } on TypeError {
      return const [];
    }
  }

  Future<void> writeSessions(List<ChatSession> sessions) {
    final encoded = jsonEncode(sessions.map(_sessionToJson).toList());
    return _storage.write(key: _sessionsKey, value: encoded);
  }

  Future<Map<String, List<ChatMessage>>> readAllMessages() async {
    final raw = await _storage.read(key: _messagesKey);
    if (raw == null) return const {};
    try {
      final decoded = jsonDecode(raw) as Map<String, dynamic>;
      return decoded.map(
        (sessionId, messages) => MapEntry(
          sessionId,
          (messages as List<dynamic>)
              .map((m) => _messageFromJson(m as Map<String, dynamic>))
              .toList(),
        ),
      );
    } on FormatException {
      return const {};
    } on TypeError {
      return const {};
    }
  }

  Future<void> writeMessagesForSession(
    String sessionId,
    List<ChatMessage> messages,
  ) async {
    final all = await readAllMessages();
    final updated = {...all, sessionId: messages};
    final encoded = jsonEncode(
      updated.map(
        (sid, msgs) => MapEntry(sid, msgs.map(_messageToJson).toList()),
      ),
    );
    await _storage.write(key: _messagesKey, value: encoded);
  }

  Future<String?> readLastActiveSessionId() {
    return _storage.read(key: _lastActiveKey);
  }

  Future<void> writeLastActiveSessionId(String? sessionId) {
    if (sessionId == null) {
      return _storage.delete(key: _lastActiveKey);
    }
    return _storage.write(key: _lastActiveKey, value: sessionId);
  }

  Future<Map<String, String>> readSavedMessageEntryIds() async {
    final raw = await _storage.read(key: _savedMessageEntryIdsKey);
    if (raw == null) return const {};
    try {
      final decoded = jsonDecode(raw) as Map<String, dynamic>;
      return decoded.map((k, v) => MapEntry(k, v as String));
    } on FormatException {
      return const {};
    } on TypeError {
      return const {};
    }
  }

  Future<void> writeSavedMessageEntryIds(Map<String, String> ids) {
    return _storage.write(key: _savedMessageEntryIdsKey, value: jsonEncode(ids));
  }

  /// Deletes all four of this cache's keys — part of account deletion's
  /// "any other locally held user data" clear (FR-019, research.md R9).
  Future<void> clear() async {
    await Future.wait([
      _storage.delete(key: _sessionsKey),
      _storage.delete(key: _messagesKey),
      _storage.delete(key: _lastActiveKey),
      _storage.delete(key: _savedMessageEntryIdsKey),
    ]);
  }

  Map<String, dynamic> _sessionToJson(ChatSession s) => {
    'id': s.id,
    'title': s.title,
    'personaSnapshot': s.personaSnapshot.name,
    'userMessageCount': s.userMessageCount,
    'lastUserMessageAt': s.lastUserMessageAt?.toUtc().toIso8601String(),
    'createdAt': s.createdAt.toUtc().toIso8601String(),
    'updatedAt': s.updatedAt.toUtc().toIso8601String(),
  };

  ChatSession _sessionFromJson(Map<String, dynamic> data) => ChatSession(
    id: data['id'] as String,
    title: data['title'] as String,
    personaSnapshot: ChatPersona.values.byName(
      data['personaSnapshot'] as String,
    ),
    userMessageCount: data['userMessageCount'] as int,
    lastUserMessageAt: (data['lastUserMessageAt'] as String?) == null
        ? null
        : DateTime.parse(data['lastUserMessageAt'] as String),
    createdAt: DateTime.parse(data['createdAt'] as String),
    updatedAt: DateTime.parse(data['updatedAt'] as String),
  );

  Map<String, dynamic> _messageToJson(ChatMessage m) => {
    'id': m.id,
    'sessionId': m.sessionId,
    'role': m.role.name,
    'content': m.content,
    'seq': m.seq,
    'status': m.status.name,
    'retryCount': m.retryCount,
    'createdAt': m.createdAt.toUtc().toIso8601String(),
  };

  ChatMessage _messageFromJson(Map<String, dynamic> data) => ChatMessage(
    id: data['id'] as String,
    sessionId: data['sessionId'] as String,
    role: ChatRole.values.byName(data['role'] as String),
    content: data['content'] as String,
    seq: data['seq'] as int,
    status: ChatMessageStatus.values.byName(data['status'] as String),
    retryCount: data['retryCount'] as int,
    createdAt: DateTime.parse(data['createdAt'] as String),
  );
}

import 'dart:convert';

import 'package:cerne/features/entries/domain/entities/entry.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

/// On-device, cross-restart persistence for the entries the user has
/// already seen (the PRD's "local read cache" — requirements.md line 50/125:
/// results from it stay visible offline and reconcile with the server on
/// reconnect, with no duplicates). Keychain-backed, same pattern as
/// `VaultSecureStorage` — journal content is personal data, so it stays
/// encrypted at rest like the PIN it already sits behind.
///
/// Distinct from `EntriesRepositoryImpl`'s in-memory `cachedEntries`: that
/// field only ever held optimistic just-created entries for this process's
/// lifetime (research.md R8, 003-multimodal-capture). This class is what
/// makes that same list survive an app restart, which is what a cold open
/// on an already-offline device needs (closing snapshot at unit completion
/// did not cover this path — see Meus Registros intervention report).
class EntriesLocalCache {
  EntriesLocalCache({FlutterSecureStorage? storage})
    : _storage = storage ?? const FlutterSecureStorage();

  final FlutterSecureStorage _storage;

  static const _key = 'entriesLocalCache';

  Future<List<Entry>> readAll() async {
    final raw = await _storage.read(key: _key);
    if (raw == null) return const [];
    try {
      final decoded = jsonDecode(raw) as List<dynamic>;
      return decoded.map((e) => _fromJson(e as Map<String, dynamic>)).toList();
    } on FormatException {
      return const [];
    } on TypeError {
      return const [];
    }
  }

  Future<void> writeAll(List<Entry> entries) {
    final encoded = jsonEncode(entries.map(_toJson).toList());
    return _storage.write(key: _key, value: encoded);
  }

  /// Deletes this cache's one key — part of account deletion's "any other
  /// locally held user data" clear (FR-019, research.md R9).
  Future<void> clear() => _storage.delete(key: _key);

  Map<String, dynamic> _toJson(Entry e) => {
    'id': e.id,
    'content': e.content,
    'source': e.source.name,
    'chatMessageId': e.chatMessageId,
    'occurredAt': e.occurredAt.toUtc().toIso8601String(),
    'tags': [
      for (final tag in e.tags) {'id': tag.id, 'name': tag.name},
    ],
    'piiStatus': e.piiStatus.name,
    'piiSpans': [
      for (final span in e.piiSpans)
        {'start': span.start, 'end': span.end, 'type': span.type},
    ],
    'embeddingStatus': e.embeddingStatus.name,
    'mediaDurationSeconds': e.mediaDurationSeconds,
    'serverRevision': e.serverRevision,
    'createdAt': e.createdAt.toUtc().toIso8601String(),
    'updatedAt': e.updatedAt.toUtc().toIso8601String(),
    'similarity': e.similarity,
  };

  Entry _fromJson(Map<String, dynamic> data) => Entry(
    id: data['id'] as String,
    content: data['content'] as String,
    source: EntrySource.values.byName(data['source'] as String),
    chatMessageId: data['chatMessageId'] as String?,
    occurredAt: DateTime.parse(data['occurredAt'] as String),
    tags: (data['tags'] as List<dynamic>)
        .map(
          (t) => EntryTag(
            id: (t as Map<String, dynamic>)['id'] as String,
            name: t['name'] as String,
          ),
        )
        .toList(),
    piiStatus: PiiStatus.values.byName(data['piiStatus'] as String),
    piiSpans: (data['piiSpans'] as List<dynamic>)
        .map(
          (s) => PiiSpan(
            start: (s as Map<String, dynamic>)['start'] as int,
            end: s['end'] as int,
            type: s['type'] as String,
          ),
        )
        .toList(),
    embeddingStatus: EmbeddingStatus.values.byName(
      data['embeddingStatus'] as String,
    ),
    mediaDurationSeconds: data['mediaDurationSeconds'] as int?,
    serverRevision: data['serverRevision'] as int,
    createdAt: DateTime.parse(data['createdAt'] as String),
    updatedAt: DateTime.parse(data['updatedAt'] as String),
    similarity: (data['similarity'] as num?)?.toDouble(),
  );
}

