24	/// "Meus Registros" (data-model.md). The `ScrollController` is created once
25	/// and never recreated across `BlocBuilder` rebuilds, which is what
26	/// preserves scroll position across state changes (FR-003/FR-007).
27	class RecordsPage extends StatefulWidget {
28	  const RecordsPage({super.key});
29	
30	  @override
31	  State<RecordsPage> createState() => _RecordsPageState();
32	}
33	
34	class _RecordsPageState extends State<RecordsPage> {
35	  final _scrollController = ScrollController();
36	  late final StreamSubscription<void> _reauthSubscription;
37	  bool _isOpeningExportSheet = false;
38	
39	  @override
40	  void initState() {
41	    super.initState();
42	    // `RecordsStarted` is dispatched once by the route builder itself
43	    // (`AppRoutes.records`, app_router.dart) right after `RecordsBloc` is
44	    // constructed — not here, to avoid double-fetching the first page.
45	    _scrollController.addListener(_maybeRequestNextPage);
46	    // The one sanctioned cross-bloc touch point (research.md R5) — lives in
47	    // this widget, never inside `RecordsBloc` itself.
48	    _reauthSubscription = context.read<RecordsBloc>().reauthRequired.listen((_) {
49	      if (!mounted) return;
50	      context.read<SessionBloc>().add(const AuthExpiredDetected());
51	    });
52	  }
53	
54	  void _maybeRequestNextPage() {
55	    if (!_scrollController.hasClients) return;
56	    final position = _scrollController.position;
57	    if (position.pixels >= position.maxScrollExtent - 200) {
58	      context.read<RecordsBloc>().add(const NextPageRequested());
59	    }
60	  }
61	
62	  @override
63	  void dispose() {
64	    _scrollController.dispose();
65	    _reauthSubscription.cancel();
66	    super.dispose();
67	  }
68	
69	  @override
70	  Widget build(BuildContext context) {
71	    return Scaffold(
72	      backgroundColor: DesignTokens.colorSurfaceBg,
73	      body: SafeArea(
74	        child: Column(
75	          children: [
76	            _Header(onExportPressed: () => _openExportSheet(context)),
77	            _SearchBar(),
78	            BlocBuilder<RecordsBloc, RecordsState>(
79	              builder: (context, state) {
80	                final isOffline = state is RecordsLoaded &&
81	                    (state.pageLoadFailure is NetworkOfflineFailure ||
82	                        state.criteriaLoadFailure is NetworkOfflineFailure);
83	                if (!isOffline) return const SizedBox.shrink();
84	                return Padding(
85	                  padding: const EdgeInsets.fromLTRB(
86	                    DesignTokens.spacingMd,
87	                    0,
88	                    DesignTokens.spacingMd,
89	                    DesignTokens.spacingSm,
90	                  ),
91	                  child: Align(
92	                    alignment: Alignment.centerLeft,
93	                    child: Text(
94	                      'Busca limitada ao que está salvo no aparelho.',
95	                      style: DesignTokens.textBodyMd.copyWith(
96	                        color: DesignTokens.colorInfoOffline,
97	                      ),
98	                    ),
99	                  ),
100	                );
101	              },
102	            ),
103	            BlocBuilder<RecordsBloc, RecordsState>(
104	              builder: (context, state) {
105	                if (state is! RecordsLoaded || state.activeChips.isEmpty) {
106	                  return const SizedBox.shrink();
107	                }
108	                return Padding(
109	                  padding: const EdgeInsets.fromLTRB(
110	                    DesignTokens.spacingMd,
111	                    0,
112	                    DesignTokens.spacingMd,
113	                    DesignTokens.spacingMd,
114	                  ),
115	                  child: ActiveFilterChipsRow(chips: state.activeChips),
116	                );
117	              },
118	            ),
119	            Expanded(
120	              child: BlocBuilder<RecordsBloc, RecordsState>(
121	                builder: (context, state) => switch (state) {
122	                  RecordsLoading() => const Center(child: CircularProgressIndicator()),
123	                  RecordsLoadFailure(:final failure) => _LoadFailureView(message: failure.message),
124	                  RecordsLoaded() => _buildLoaded(context, state),
125	                },
126	              ),
127	            ),
128	          ],
129	        ),
130	      ),
131	    );
132	  }
