4	/// elevation value used anywhere in the app (Constitution Principle IV; RNF08).
5	/// Transcribed verbatim from docs/input/prototype/prototype-extract.md §3.
6	class DesignTokens {
7	  const DesignTokens._();
8	
9	  // Colors
10	  static const Color colorPrimary = Color(0xFF1F3D34);
11	  static const Color colorPrimaryPressed = Color(0xFF16281F);
